package app.fableshot.android.ui

/** Canonical definitions used at every occurrence of a registered term. */
object GlossaryRegistry {
    val definitions = linkedMapOf(
        "Область расчёта" to "Показывает, какие стрелы участвуют в подробных показателях. Одинаковые сохранённые условия по умолчанию объединяются во всю тренировку. Другую часть можно выбрать явно. Разные дистанции, мишени или оборудование не смешиваются: выбирается совместимая группа. Верхние раунды и отдельно подписанный норматив относятся ко всей тренировке.",
        "Бонус за стабильность" to "Дополнительные очки CG3 за похожие средние результаты серий в выбранной области расчёта. 0,35 / 1 означает 0,35 дополнительного очка из одного возможного, а не точность 35%. Одна заметно слабая серия тоже влияет на итог. Начальные 1–2 серии ещё не получают межсерийный бонус. В стандартном профиле максимум +1, в профиле без координат +5.",
        "Стабильность" to "Насколько похож средний балл разных серий, выбранных для расчёта. Одинаковые средние дают 1; отклонения снижают показатель. Это не средний балл, не число десяток и не кучность. Учитываются все выбранные зачётные серии, в том числе ранние слабые. Формула CG3: T = max(0, 1 − D / 0,15), где D — взвешенное стандартное отклонение средних, делённых на 10.",
        "Бонус за кучность" to "Дополнительные очки CG3 за плотность стрел внутри каждой серии. Это отдельный бонус, а не сам измеренный разброс в миллиметрах. Ноль бонуса возможен при известных координатах: объединённый внутриcерийный RMS достиг 10% радиуса мишени или больше. В полном стандартном зачёте максимум +4, для одной или двух серий +5. Меньший RMS даёт больший бонус; положение центра группы отдельно на него не влияет.",
        "Отсчёт в фоне" to "Сворачивание и блокировка телефона не ставят таймер на паузу: время считается по монотонным часам, включая время сна телефона. При возвращении показывается фактический остаток. Пауза включается только вручную. Системный будильник/уведомление не планируется, сигнал в заблокированном состоянии не гарантируется. Закрытие процесса или завершение тренировки сбрасывает отсчёт; сохранённые длительности остаются.",
        "Присвоенный разряд" to "Отметка о присвоенном разряде или звании, которую ты вносишь сам. Можно указать дисциплину, категорию, дату и приказ. Приложение не проверяет присвоение внешним реестром и не повышает эту отметку по тренировочным очкам. При выборе новой текущей отметки прежняя остаётся в истории. Срок действия автоматически не вычисляется.",
        "ЕВСК" to "Единая всероссийская спортивная классификация. Здесь сравниваются классические очки с нормами квалификационного упражнения из приложения 34 к приказу Минспорта №201 от 10.03.2026. Для официального присвоения также нужны предусмотренные возраст, статус соревнования и другие условия. Тренировка сама по себе разряд не присваивает. Историческая применимость этой редакции по дате занятия автоматически не подтверждается.",
        "Разряд" to "Спортивный уровень по выбранной системе нормативов. Во время тренировки здесь показан прогноз по среднему баллу уже введённых зачётных стрел. Сравнение относится к указанному формату и категории. Пустые поля не учитываются, M считается нулём. Прогноз не означает выполнение полного упражнения или присвоение разряда.",
        "Разброс RMS" to "Среднее квадратичное расстояние отмеченных попаданий от их средней точки. Меньше значение — плотнее группа. Единица зависит от шкалы: миллиметры или доли радиуса. Для нескольких занятий показатель также учитывает перемещение группы между ними; это не внутриcерийный бонус CG3.",
        "RMS" to "Среднее квадратичное расстояние попаданий от их средней точки. Чем меньше, тем плотнее группа. Для оценки нужны подтверждённые координаты.",
        "Кучность" to "Насколько близко друг к другу попали стрелы. Плотная группа может находиться в стороне от центра: кучность и точность попадания в центр — разные показатели.",
        "Смещение" to "Расстояние от центра мишени до средней точки попаданий. Меньше расстояние — ближе центр группы к центру мишени.",
        "Общие очки" to "Оценка по выбранной системе, учитывающая классические очки и доступные показатели качества стрельбы. Состав зависит от полноты серий и достоверности координат. Это не официальный спортивный результат.",
        "Прогресс" to "Изменение среднего балла относительно зафиксированного обычного уровня по похожим тренировкам. Рост с 5 до 6 баллов за стрелу означает +20%. Положительное значение означает улучшение. При нулевой базе показываем прибавку среднего в баллах вместо процента. При недостатке сопоставимых занятий оценка может быть предварительной или недоступной.",
        "База сравнения" to "Несколько предыдущих похожих тренировок, использованных для определения обычного уровня. Для занятия база фиксируется и не заменяется случайно при смене фильтров.",
        "Процентные пункты" to "Разница между двумя процентными долями. Рост с 50% до 60% — это 10 процентных пунктов, а относительный рост составляет 20%.",
        "Распределение попаданий" to "Количество и доля стрел в каждой оценочной зоне мишени. Промахи обозначаются M; X входит в десятки и может дополнительно учитываться отдельно.",
        "Гэндальф" to "Волшебник из историй Толкина. В достижении — шутка про мудрую памятку, не оценка магии техники.",
        "Мерида" to "Лучница, героиня мультфильма «Храбрая сердцем».",
        "Кэтнисс" to "Героиня «Голодных игр», известная стрельбой из лука.",
        "Леголас" to "Эльф-лучник из «Властелина колец».",
        "Робин" to "Робин Гуд — легендарный английский лучник. Плотная группа отметок не доказывает расколотую стрелу.",
        "Артемида" to "Древнегреческая богиня охоты, часто изображаемая с луком.",
        "X-Men" to "Команда супергероев. Здесь игра с шестью попаданиями в X."
    )

    fun matching(text: String): Map<String,String> = definitions.filterKeys { text.contains(it,ignoreCase=true) }
}
